#!/usr/bin/env node
/**
 * AI CLI Hub - Unified MCP Server
 *
 * Provides unified access to Gemini CLI, Qwen Code, and OpenCode functionalities
 * through the Model Context Protocol (MCP).
 */
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
// Import tool implementations
import { createGeminiTools } from "./tools/gemini.js";
import { createQwenTools } from "./tools/qwen.js";
import { createOpenCodeTools } from "./tools/opencode.js";
import { createFileOperationTools } from "./tools/file-ops.js";
import { createGitTools } from "./tools/git.js";
import { createAuthTools, executeAuthTool } from "./tools/auth.js";
// Import configuration and authentication
import { loadConfig } from "./config.js";
import { Logger } from "./logger.js";
import { OAuthManager } from "./auth/oauth-manager.js";
class AICliHubServer {
    server;
    config;
    logger;
    tools = new Map();
    oauthManager;
    constructor() {
        this.logger = new Logger("ai-cli-hub");
        this.server = new Server({
            name: "ai-cli-hub",
            version: "0.1.0"
        }, {
            capabilities: {
                tools: {},
            }
        });
        this.setupHandlers();
    }
    setupHandlers() {
        // List available tools
        this.server.setRequestHandler(ListToolsRequestSchema, async () => {
            return {
                tools: Array.from(this.tools.values())
            };
        });
        // Execute tool calls
        this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
            const { name, arguments: args } = request.params;
            this.logger.info(`Tool called: ${name}`, { args });
            try {
                const result = await this.executeTool(name, args || {});
                return {
                    content: [
                        {
                            type: "text",
                            text: JSON.stringify(result, null, 2)
                        }
                    ]
                };
            }
            catch (error) {
                this.logger.error(`Tool execution failed: ${name}`, { error });
                return {
                    content: [
                        {
                            type: "text",
                            text: `Error: ${error instanceof Error ? error.message : String(error)}`
                        }
                    ],
                    isError: true
                };
            }
        });
    }
    async executeTool(name, args) {
        if (name.startsWith("gemini_")) {
            return this.executeGeminiTool(name, args);
        }
        else if (name.startsWith("qwen_")) {
            return this.executeQwenTool(name, args);
        }
        else if (name.startsWith("opencode_")) {
            return this.executeOpenCodeTool(name, args);
        }
        else if (name.startsWith("file_")) {
            return this.executeFileOperationTool(name, args);
        }
        else if (name.startsWith("git_")) {
            return this.executeGitTool(name, args);
        }
        else if (name.startsWith("auth_")) {
            return executeAuthTool(name, args, this.oauthManager);
        }
        else {
            throw new Error(`Unknown tool: ${name}`);
        }
    }
    async executeGeminiTool(name, args) {
        // Check authentication status (for OAuth-enabled tools)
        if (this.config.engines.gemini?.useOAuth) {
            const token = await this.oauthManager.getStoredToken('gemini');
            if (!token) {
                throw new Error('Gemini authentication required. Please authenticate first.');
            }
        }
        // Execute external gemini command (following existing Python implementation pattern)
        return this.executeExternalCommand('gemini', name, args);
    }
    async executeQwenTool(name, args) {
        // Check authentication status (for OAuth-enabled tools)
        if (this.config.engines.qwen?.useOAuth) {
            const token = await this.oauthManager.getStoredToken('qwen');
            if (!token) {
                throw new Error('Qwen authentication required. Please authenticate first.');
            }
        }
        // Execute external qwen command (following existing Python implementation pattern)
        return this.executeExternalCommand('qwen', name, args);
    }
    async executeOpenCodeTool(name, args) {
        // OpenCode may use different authentication methods
        // Check if OAuth is configured for this engine
        if (this.config.engines.opencode?.useOAuth) {
            const token = await this.oauthManager.getStoredToken('opencode');
            if (!token) {
                throw new Error('OpenCode OAuth authentication required. Please authenticate first.');
            }
        }
        // TODO: Implement OpenCode tool execution
        return { message: `OpenCode tool ${name} executed`, args };
    }
    async executeFileOperationTool(name, args) {
        // TODO: Implement file operation tool execution
        return { message: `File operation ${name} executed`, args };
    }
    /**
     * Execute external command (following existing Python MCP implementation)
     */
    async executeExternalCommand(engineType, toolName, args) {
        try {
            // Map tool names to command arguments based on existing Python implementation
            const commandArgs = this.buildCommandArgs(engineType, toolName, args);
            this.logger.info(`Executing external command`, { engineType, toolName, commandArgs });
            // Prepare environment with authentication tokens
            const env = await this.prepareEnvironment(engineType);
            // Execute command with timeout
            const result = await this.runCommand(commandArgs, env);
            return {
                success: true,
                result: result.stdout,
                engineType,
                toolName
            };
        }
        catch (error) {
            this.logger.error(`External command failed`, { engineType, toolName, error });
            return {
                success: false,
                error: error instanceof Error ? error.message : String(error),
                engineType,
                toolName
            };
        }
    }
    buildCommandArgs(engineType, toolName, args) {
        const baseCommand = [engineType];
        // Map MCP tool names to CLI arguments following existing Python patterns
        switch (toolName) {
            case `${engineType}_chat`:
                baseCommand.push('-p', args.prompt || args.message || '');
                if (args.model)
                    baseCommand.push('-m', args.model);
                if (args.sandbox)
                    baseCommand.push('-s');
                if (args.yolo)
                    baseCommand.push('-y');
                break;
            case `${engineType}_analyze_codebase`:
            case `${engineType}_analyze_document`:
                const analyzePrompt = `Analyze: ${args.content || args.path || args.directory}`;
                baseCommand.push('-p', analyzePrompt);
                if (args.analysisType)
                    baseCommand.push('--analysis-type', args.analysisType);
                break;
            case `${engineType}_generate_code`:
                baseCommand.push('-p', `Generate code: ${args.prompt}`);
                if (args.language)
                    baseCommand.push('--language', args.language);
                break;
            default:
                // Generic command handling
                baseCommand.push('-p', args.prompt || JSON.stringify(args));
                break;
        }
        return baseCommand;
    }
    async prepareEnvironment(engineType) {
        const env = { ...process.env };
        // Add OAuth tokens to environment if available
        try {
            const token = await this.oauthManager.getStoredToken(engineType);
            if (token) {
                env[`${engineType.toUpperCase()}_ACCESS_TOKEN`] = token.access_token;
                if (token.refresh_token) {
                    env[`${engineType.toUpperCase()}_REFRESH_TOKEN`] = token.refresh_token;
                }
            }
        }
        catch (error) {
            // Token not available - proceed without OAuth (may use API keys instead)
            this.logger.debug(`No OAuth token available for ${engineType}`);
        }
        return env;
    }
    async runCommand(args, env, timeout = 30000) {
        const { spawn } = await import('child_process');
        return new Promise((resolve, reject) => {
            const child = spawn(args[0], args.slice(1), {
                env,
                stdio: ['pipe', 'pipe', 'pipe'],
                timeout
            });
            let stdout = '';
            let stderr = '';
            child.stdout?.on('data', (data) => {
                stdout += data.toString();
            });
            child.stderr?.on('data', (data) => {
                stderr += data.toString();
            });
            child.on('close', (code) => {
                if (code === 0) {
                    resolve({ stdout, stderr });
                }
                else {
                    reject(new Error(`Command failed with exit code ${code}: ${stderr}`));
                }
            });
            child.on('error', (error) => {
                reject(error);
            });
            // Handle timeout
            const timeoutId = setTimeout(() => {
                child.kill('SIGTERM');
                reject(new Error(`Command timed out after ${timeout}ms`));
            }, timeout);
            child.on('close', () => {
                clearTimeout(timeoutId);
            });
        });
    }
    async executeGitTool(name, args) {
        // TODO: Implement Git tool execution
        return { message: `Git tool ${name} executed`, args };
    }
    async initialize() {
        try {
            // Load configuration
            this.config = await loadConfig();
            this.logger.info("Configuration loaded", {
                enabledEngines: Object.keys(this.config.engines).filter(k => {
                    const engine = this.config.engines[k];
                    return engine?.enabled;
                })
            });
            // Initialize OAuth manager
            this.oauthManager = new OAuthManager();
            // Check authentication status for OAuth-enabled engines
            const authStatus = await this.oauthManager.checkAuthenticationStatus();
            this.logger.info("OAuth authentication status", authStatus);
            // Register tools based on enabled engines
            await this.registerTools();
            this.logger.info("AI CLI Hub initialized", {
                toolCount: this.tools.size,
                tools: Array.from(this.tools.keys()),
                authenticatedProviders: Object.entries(authStatus).filter(([, auth]) => auth).map(([provider]) => provider)
            });
        }
        catch (error) {
            this.logger.error("Failed to initialize server", { error });
            throw error;
        }
    }
    async registerTools() {
        // Register authentication tools (always enabled)
        const authTools = await createAuthTools();
        for (const [name, tool] of authTools.entries()) {
            this.tools.set(name, tool);
        }
        // Register Gemini tools if enabled
        if (this.config.engines.gemini?.enabled) {
            const geminiTools = await createGeminiTools(this.config.engines.gemini);
            for (const [name, tool] of geminiTools.entries()) {
                this.tools.set(name, tool);
            }
        }
        // Register Qwen tools if enabled  
        if (this.config.engines.qwen?.enabled) {
            const qwenTools = await createQwenTools(this.config.engines.qwen);
            for (const [name, tool] of qwenTools.entries()) {
                this.tools.set(name, tool);
            }
        }
        // Register OpenCode tools if enabled
        if (this.config.engines.opencode?.enabled) {
            const opencodeTools = await createOpenCodeTools(this.config.engines.opencode);
            for (const [name, tool] of opencodeTools.entries()) {
                this.tools.set(name, tool);
            }
        }
        // Register file operation tools if enabled
        if (this.config.features.fileOperations) {
            const fileTools = await createFileOperationTools();
            for (const [name, tool] of fileTools.entries()) {
                this.tools.set(name, tool);
            }
        }
        // Register Git tools if enabled
        if (this.config.features.gitIntegration) {
            const gitTools = await createGitTools();
            for (const [name, tool] of gitTools.entries()) {
                this.tools.set(name, tool);
            }
        }
    }
    async start() {
        const transport = new StdioServerTransport();
        await this.server.connect(transport);
        this.logger.info("AI CLI Hub MCP Server started");
    }
}
// Main execution
async function main() {
    const server = new AICliHubServer();
    try {
        await server.initialize();
        await server.start();
    }
    catch (error) {
        console.error("Failed to start AI CLI Hub:", error);
        process.exit(1);
    }
}
if (import.meta.url === `file://${process.argv[1]}`) {
    main().catch(console.error);
}
export { AICliHubServer };
