#!/usr/bin/env node
/**
 * AI CLI Hub - CLI Entry Point
 *
 * npx実行可能なCLIエントリーポイント
 * 使用方法: npx ai-cli-hub [options]
 */
import { program } from 'commander';
import { AICliHubServer } from '../index.js';
import { Logger } from '../logger.js';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { existsSync, mkdirSync } from 'fs';
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const logger = new Logger('ai-cli-hub-cli');
// バージョン情報の取得
async function getVersion() {
    try {
        const packageJsonPath = join(__dirname, '../../package.json');
        const packageJson = await import(packageJsonPath, { assert: { type: 'json' } });
        return packageJson.default.version;
    }
    catch {
        return '0.1.0';
    }
}
// 設定ディレクトリの初期化
function initializeConfigDirectory() {
    const homeDir = process.env.HOME || process.env.USERPROFILE || '/tmp';
    const configDir = join(homeDir, '.ai-cli-hub');
    if (!existsSync(configDir)) {
        mkdirSync(configDir, { recursive: true });
        mkdirSync(join(configDir, 'tokens'), { recursive: true });
        logger.info(`設定ディレクトリを作成しました: ${configDir}`);
    }
    return configDir;
}
// デフォルト設定ファイルの作成
async function createDefaultConfig(configDir) {
    const configFile = join(configDir, 'config.json');
    if (!existsSync(configFile)) {
        const defaultConfig = {
            engines: {
                qwen: {
                    enabled: true,
                    model: "qwen3-coder-plus",
                    useOAuth: false,
                    timeout: 30000
                },
                gemini: {
                    enabled: true,
                    model: "gemini-2.5-pro",
                    useOAuth: false,
                    grounding: true,
                    timeout: 30000
                },
                opencode: {
                    enabled: true,
                    provider: "anthropic",
                    useOAuth: false,
                    timeout: 30000
                }
            },
            features: {
                fileOperations: true,
                gitIntegration: true
            },
            server: {
                logLevel: "info",
                timeout: 120000
            }
        };
        const { writeFileSync } = await import('fs');
        writeFileSync(configFile, JSON.stringify(defaultConfig, null, 2));
        logger.info(`デフォルト設定ファイルを作成しました: ${configFile}`);
    }
}
async function main() {
    const version = await getVersion();
    program
        .name('ai-cli-hub')
        .description('統合AI CLI Hub MCPサーバー')
        .version(version);
    program
        .command('start')
        .description('MCPサーバーを起動')
        .option('-p, --port <port>', 'サーバーポート (現在はstdio固定)', '3000')
        .option('-c, --config <path>', '設定ファイルのパス')
        .option('--log-level <level>', 'ログレベル (debug|info|warn|error)', 'info')
        .action(async (options) => {
        try {
            logger.info('🚀 AI CLI Hub MCPサーバーを起動中...');
            // 設定ディレクトリの初期化
            const configDir = initializeConfigDirectory();
            await createDefaultConfig(configDir);
            // 環境変数の設定
            if (!process.env.AI_CLI_HUB_CONFIG_DIR) {
                process.env.AI_CLI_HUB_CONFIG_DIR = configDir;
            }
            if (options.logLevel) {
                process.env.LOG_LEVEL = options.logLevel;
            }
            // サーバーの起動
            const server = new AICliHubServer();
            await server.initialize();
            await server.start();
            logger.info('✅ AI CLI Hub MCPサーバーが正常に起動しました');
            logger.info('📋 Claude Desktop等のMCPクライアントから接続可能です');
        }
        catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            logger.error('❌ サーバー起動に失敗しました:', { error: errorMessage });
            process.exit(1);
        }
    });
    program
        .command('init')
        .description('設定ファイルとディレクトリを初期化')
        .action(async () => {
        try {
            logger.info('🔧 AI CLI Hub設定を初期化中...');
            const configDir = initializeConfigDirectory();
            await createDefaultConfig(configDir);
            logger.info('✅ 初期化完了');
            logger.info(`📁 設定ディレクトリ: ${configDir}`);
            logger.info(`⚙️  設定ファイル: ${join(configDir, 'config.json')}`);
            logger.info(`🔐 トークン保存先: ${join(configDir, 'tokens')}`);
            logger.info('');
            logger.info('次のステップ:');
            logger.info('1. npx ai-cli-hub start でサーバー起動');
            logger.info('2. Claude DesktopのMCP設定に追加');
            logger.info('3. OAuth認証で各AIエンジンを有効化');
        }
        catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            logger.error('❌ 初期化に失敗しました:', { error: errorMessage });
            process.exit(1);
        }
    });
    program
        .command('config')
        .description('設定ファイルの場所を表示')
        .action(() => {
        const configDir = initializeConfigDirectory();
        const configFile = join(configDir, 'config.json');
        console.log('📁 AI CLI Hub設定');
        console.log(`設定ディレクトリ: ${configDir}`);
        console.log(`設定ファイル: ${configFile}`);
        console.log(`トークン保存先: ${join(configDir, 'tokens')}`);
        console.log(`設定ファイル存在: ${existsSync(configFile) ? '✅' : '❌'}`);
    });
    program
        .command('demo')
        .description('デモ用モックコマンドをセットアップ')
        .action(async () => {
        try {
            logger.info('🎭 デモ用モックコマンドをセットアップ中...');
            const { spawn } = await import('child_process');
            const demoScript = join(__dirname, '../../demo/mock-ai-commands.sh');
            if (!existsSync(demoScript)) {
                logger.error('❌ デモスクリプトが見つかりません:', { path: demoScript });
                process.exit(1);
            }
            const child = spawn('bash', [demoScript], {
                stdio: 'inherit',
                cwd: join(__dirname, '../..')
            });
            child.on('close', (code) => {
                if (code === 0) {
                    logger.info('✅ デモ環境セットアップ完了');
                    logger.info('テスト用コマンドを実行: source demo/setup-mock-env.sh');
                }
                else {
                    logger.error('❌ デモセットアップ失敗');
                    process.exit(code || 1);
                }
            });
        }
        catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            logger.error('❌ デモセットアップエラー:', { error: errorMessage });
            process.exit(1);
        }
    });
    // デフォルトアクション（引数なしの場合）
    if (process.argv.length === 2) {
        program.outputHelp();
    }
    else {
        await program.parseAsync(process.argv);
    }
}
// エラーハンドリング
process.on('uncaughtException', (error) => {
    logger.error('未処理例外:', { error: error.message });
    process.exit(1);
});
process.on('unhandledRejection', (reason) => {
    logger.error('未処理Promise拒否:', { reason });
    process.exit(1);
});
// シグナルハンドリング
process.on('SIGINT', () => {
    logger.info('🛑 AI CLI Hubを終了中...');
    process.exit(0);
});
process.on('SIGTERM', () => {
    logger.info('🛑 AI CLI Hubを終了中...');
    process.exit(0);
});
if (import.meta.url === `file://${process.argv[1]}`) {
    main().catch(console.error);
}
export { main };
